/**
 * Polyfork low-poly models the island uses (requirement.md v1.45 §19.1–19.2; picks in
 * docs/polyfork-picks.json, files in public/models/pf/, credits generated by
 * scripts/polyfork_models.py). Only these GLB files are hosted; Polyfork's .mjs code is never used.
 *
 * `fit` says how a model is sized into tile units after it is turned to face +z (cars: +x):
 *   footprint — the larger of width/depth becomes this many tiles (houses, buildings)
 *   height    — total height in tiles (trees)
 *   metres    — real size at 10 m per tile (cars, props, people: they stay in proportion)
 */
export type LpCategory = 'house' | 'tower' | 'building' | 'tree' | 'car' | 'prop';

export type LpFit = { footprint: number } | { height: number } | { metres: true };

export interface LpSpec {
  file: string;
  cat: LpCategory;
  fit: LpFit;
  /** Extra turn (radians) so the model's front faces +z like our box model (props without a door). */
  yaw?: number;
  /** A lamp: light colours near the top are its bulbs, lit at night like windows. */
  lamp?: boolean;
}

/** Tiles per metre for `metres` fits (a car is about half a tile long, like our own). */
export const TILES_PER_METRE = 0.1;

const house = (file: string, footprint = 0.92): LpSpec => ({ file, cat: 'house', fit: { footprint } });
const tower = (file: string, footprint = 0.94): LpSpec => ({ file, cat: 'tower', fit: { footprint } });
const tree = (file: string, height: number): LpSpec => ({ file, cat: 'tree', fit: { height } });
const car = (file: string): LpSpec => ({ file, cat: 'car', fit: { metres: true } });
const prop = (file: string, fit: LpFit, extra: Partial<LpSpec> = {}): LpSpec => ({ file, cat: 'prop', fit, ...extra });

